import{_ as o,o as d,c as i,ag as a}from"./chunks/framework.D9ghT4bC.js";const g=JSON.parse('{"title":"构建与测试 Android 版本","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Developers/Testing-Android-Builds.md","filePath":"zh/Developers/Testing-Android-Builds.md"}'),l={name:"zh/Developers/Testing-Android-Builds.md"};function t(u,e,n,c,r,s){return d(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="构建与测试-android-版本" tabindex="-1">构建与测试 Android 版本 <a class="header-anchor" href="#构建与测试-android-版本" aria-label="Permalink to &quot;构建与测试 Android 版本&quot;">​</a></h1><p>本文仍在完善中——欢迎贡献。其中大部分信息并非 Unciv 特有，可公开获取。</p><h2 id="运行配置" tabindex="-1">运行配置 <a class="header-anchor" href="#运行配置" aria-label="Permalink to &quot;运行配置&quot;">​</a></h2><p>成功的 Gradle sync 应该会自动创建 &quot;android&quot; 的运行配置。 如果没有，你可以尝试自己创建一个（不过如果配置缺失是因为 Gradle sync 不完整，那你很可能根本无法选择模块）：</p><ul><li>在 Android Studio 中，Run &gt; Edit configurations（务必先让 Gradle sync 成功完成）。 <ul><li>点击 &quot;+&quot; 添加新配置</li><li>选择 &quot;Android App&quot;</li><li>给配置起个名字，我们建议 &quot;Android&quot;</li><li>模块设为 <code>Unciv.android.main</code></li><li>在 Miscellaneous 标签页，我们建议勾选两个 logcat 选项</li><li>在 Debugger 标签页，我们建议勾选 <code>Automatically attach on Debug.waitForDebugger()</code></li><li>就这样，其余保持默认即可。</li></ul></li></ul><h2 id="实体设备" tabindex="-1">实体设备 <a class="header-anchor" href="#实体设备" aria-label="Permalink to &quot;实体设备&quot;">​</a></h2><p>在实体设备上调试其实最容易。 Studio 运行时会启动 adb，任何新接入且允许调试的设备都会要求确认你电脑的指纹（本教程用 USB 线，IP 是另一回事）。 一旦 adb 能看到设备、设备也授权了你的电脑，它就会出现在 &quot;android&quot; 运行配置右侧的设备下拉框中并被预选，然后你就可以像桌面版一样开始调试了。 <strong>注意</strong>：调试会话不会因为你从 Unciv 菜单选择 Exit 而结束——把它从最近任务列表划掉才能结束调试会话。不建议在 Studio 里点停止按钮。这是 Android 的特性。</p><h3 id="linux-上的-adb" tabindex="-1">Linux 上的 <code>adb</code> <a class="header-anchor" href="#linux-上的-adb" aria-label="Permalink to &quot;Linux 上的 `adb`&quot;">​</a></h3><p>要在 Linux 上用 USB 调试，可能需要准备权限。具体要求取决于发行版——不确定就搜索在线资料。 以 Mint 22.1 为例步骤如下，其他发行版应该很容易对应：</p><ul><li>确保你是 <code>plugdev</code> 组的成员（bash：<code>groups</code>）。Mint 默认就是，如果不是就添加自己（<code>sudo usermod -a -G plugdev $USER</code>）。</li><li>确保存在匹配的 udev 规则。这取决于你要连接的设备厂商。要查厂商 ID，在设备连接时运行：<code>lsusb</code>。 找到你的设备，记下 &quot;ID&quot; 后面第一个 4 位十六进制代码。很多情况下是 <code>18d1</code>——例如 LineageOS 设备大多会伪装成 18d1，即使硬件不同。</li><li>查看 <code>/etc/udev/rules.d/</code> 里已有的规则。典型文件名是 <code>51-android.rules</code>。这些是文本文件且都会被处理，所以根据名字猜，不确定就全部检查。</li><li>编辑或创建规则文件。在 Mint 22+ 上可以用 sudo 运行 xed，否则可以选 nano 等其他编辑器。<code>sudo xed /etc/udev/rules.d/51-android.rules</code></li><li>典型情况下文件只有一行：<code>SUBSYSTEM==&quot;usb&quot;, ATTR{idVendor}==&quot;18d1&quot;, MODE=&quot;0666&quot;, GROUP=&quot;plugdev&quot;</code>。对，把那个 <code>18d1</code> 换成你的厂商 ID。如果文件里已有其他厂商 ID 的行，就再加一行。</li><li>保存文件~然后重启。~开个玩笑——我们是 Linux，所以 <code>sudo udevadm control --reload-rules &amp;&amp; sudo udevadm trigger</code> 就够了。</li><li>试试 <code>adb kill-server &amp;&amp; adb devices</code>：你的设备应该出现在列表里，Studio 也能与它通信了。</li><li>你可能需要从设备上重新授权你的电脑。确保没有通知栏或其他系统 UI 挡住授权弹窗。</li><li>如果还有问题，确保没有旧权限下残留的 gradle daemon：<code>./gradlew --status</code>。如果有，杀掉它们：<code>./gradlew --stop</code>（或直接跳过 status）。</li></ul><h2 id="构建-apk" tabindex="-1">构建 APK <a class="header-anchor" href="#构建-apk" aria-label="Permalink to &quot;构建 APK&quot;">​</a></h2><p>Android Studio 有菜单 &quot;Build -&gt; Build Bundle(s) / APK(s) -&gt; Build APK(s)。&quot; 这会构建一个可直接安装的 APK，完成后会弹消息询问是否在文件管理器中显示该文件。 <em><strong>重要</strong></em>：这种本地构建的 APK 是 debug 签名，与商店下载的 Unciv 不通用。你不能用其中一个更新另一个，也不能不卸载就切换——否则会丢失所有数据。 命令行等价操作是：<code>./gradlew android:assembleDebug</code>。然后到 <code>android/build/outputs/apk/debug</code> 自己找 APK。</p><h2 id="虚拟设备-avd" tabindex="-1">虚拟设备（AVD） <a class="header-anchor" href="#虚拟设备-avd" aria-label="Permalink to &quot;虚拟设备（AVD）&quot;">​</a></h2><p>（待补充）</p><ul><li>安装 Emulator</li><li>Intel HAXM：Intel 已弃用但仍推荐</li><li>下载系统镜像 <ul><li>选择：与宿主机架构匹配、不含 Google、旧版更快……？</li></ul></li><li>配置 AVD</li><li>在 AVD 上调试</li></ul><h2 id="unciv-的日志输出" tabindex="-1">Unciv 的日志输出 <a class="header-anchor" href="#unciv-的日志输出" aria-label="Permalink to &quot;Unciv 的日志输出&quot;">​</a></h2><p>Unciv 的日志系统运行在 Android SDK 日志系统之上，在传给系统之前会过滤并打标签。</p><p>与桌面版一样，它有 &#39;release&#39; 模式，会丢弃所有来自 Unciv 代码的日志。 当实际 APK 的 manifest 说 debuggable=false 时即判定为 release——这里讨论的所有可能性就都是 debug 构建。 从 Studio 运行时，用 Run 还是 Debug 按钮都一样——两者都部署 debug 构建，区别只在于是否立即附加调试器。 从 Studio 构建的 APK 也永远是 debug 构建。</p><p>因此，除非你运行商店版本，日志总是开启的。 你可以通过提供 intent extra 覆盖：在运行配置的 &quot;General&quot; 标签页的 &quot;Launch Flags&quot; 字段加上：<code>--ez debugLogging false</code>。 不用 Studio 也可以借助 activity manager 控制：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>adb shell am start com.unciv.app/com.unciv.app.AndroidLauncher --ez debugLogging true</span></span></code></pre></div><p>（或在设备终端直接 <code>am start...</code>）可以为 release（商店）构建打开日志。</p><p>通过给 Java 虚拟机提供 <code>-D</code> 选项实现的日志过滤功能，据我们所知在 Android 上无法控制。 （待补充——在桌面/Studio 的 wiki 文章里记录这些）</p><h2 id="读取-logcat" tabindex="-1">读取 logcat <a class="header-anchor" href="#读取-logcat" aria-label="Permalink to &quot;读取 logcat&quot;">​</a></h2><p>（待补充）</p><ul><li>Studio <ul><li>如果 logcat 窗口不见了：View - Tool Windows - Logcat</li></ul></li><li>Studio 的过滤 <ul><li>调试 Unciv 时，Logcat 窗口会预置匹配的过滤器，但该工具实际上能显示整个系统日志，包括其他应用的。</li><li>用 <code>package:com.unciv.app tag:Unciv</code> 作为过滤器，可以只看 Unciv 自己日志系统的输出。</li></ul></li><li>设备上的 logcat 应用 <ul><li><code>com.pluscubed.matloglibre</code>？已过时。</li></ul></li><li>logcat 应用需要 root 或特定授权 <ul><li><code>adb shell pm grant &lt;logcat app&#39;s package id&gt; android.permission.READ_LOGS</code></li></ul></li></ul>',25)])])}const h=o(l,[["render",t]]);export{g as __pageData,h as default};
